// Tema 26 · bloque 12 · págs. 117-126 de mi PDF subrayado (Ley 29/2014: ascensos —cursos de capacitación, Cabo, vacantes, concesión, no aptitud—, destinos, comisiones de servicio, situaciones administrativas: servicio activo, servicios especiales y excedencia) · 26-ia-2101…
const Z = k => (a, r, e, o, t, p, d) => ({ k, a, r, e, o, t, p, d });
const A = Z('l29');
const Q = [
// ---- pág. 117 (evaluaciones para cursos de capacitación; Cabo)
A("art. 70.2", "Evaluaciones para asistir a determinados cursos de capacitación para el ascenso", "La designación de los asistentes al curso de capacitación para el ascenso a Comandante se efectuará siguiendo el orden resultante de la evaluación que se efectúe, y su número:",
 ["no podrá ser superior al de plazas convocadas.", "no podrá ser inferior al de plazas convocadas, salvo informe en contra del Consejo Superior.", "podrá superar en un diez por ciento al de plazas convocadas, según determine el Director General.", "será el que fije el Consejo Superior de la Guardia Civil en cada convocatoria."],
 "cuyo número no podrá ser superior al de plazas convocadas", "El número de asistentes nunca supera el de plazas convocadas.", "media"),
A("art. 70.2", "Evaluaciones para asistir a determinados cursos de capacitación para el ascenso", "En la evaluación para designar a los asistentes al curso de capacitación para el ascenso a Comandante se tendrán en cuenta la puntuación obtenida en las pruebas realizadas y los méritos que reglamentariamente se determinen, cuya incidencia no deberá ser superior a un __________ de la puntuación máxima alcanzable en aquellas pruebas.",
 ["30 por cien", "40 por cien, como máximo", "20 por cien, como mínimo", "50 por cien, salvo méritos extraordinarios"],
 "cuya incidencia no deberá ser superior a un 30 por cien de la puntuación máxima alcanzable en aquellas pruebas", "Los méritos pesan como máximo un 30 por cien de la puntuación máxima de las pruebas.", "dificil"),
A("art. 70.2", "Evaluaciones para asistir a determinados cursos de capacitación para el ascenso", "Quienes, habiendo superado las pruebas para el curso de capacitación para el ascenso a Comandante, no sean designados alumnos al curso como consecuencia del número limitado de plazas convocadas:",
 ["volverán a ser evaluados en las siguientes convocatorias.", "quedarán excluidos de las siguientes convocatorias, salvo autorización del Director General.", "deberán superar de nuevo las pruebas para poder ser evaluados en la convocatoria siguiente.", "podrán ser designados alumnos del curso aunque se supere el número de plazas, previo informe."],
 "no sean designados alumnos al curso como consecuencia del número limitado de plazas convocadas, volverán a ser evaluados en las siguientes convocatorias", "Siguen siendo evaluables en convocatorias posteriores sin repetir las pruebas.", "media"),
A("art. 70.3", "Evaluaciones para asistir a determinados cursos de capacitación para el ascenso", "Quienes hayan solicitado su exclusión de la evaluación para asistir a los cursos de capacitación en una cuarta ocasión:",
 ["no volverán a ser incluidos en evaluaciones posteriores.", "volverán a ser incluidos en las evaluaciones del ciclo siguiente cuando lo soliciten.", "permanecerán en su empleo hasta su pase a la situación de reserva, sin más efectos.", "no podrán ser evaluados para el ascenso al mismo empleo durante los dos ciclos siguientes."],
 "Quienes hayan solicitado su exclusión en una cuarta ocasión no volverán a ser incluidos en evaluaciones posteriores", "Se puede pedir la exclusión hasta tres veces; a la cuarta ya no se incluye más.", "dificil"),
A("art. 70.1", "Evaluaciones para asistir a determinados cursos de capacitación para el ascenso", "La designación de quienes deban entrar en evaluación para asistir a los cursos de capacitación y de los que asistirán a los citados cursos corresponderá:",
 ["al Director General, previo informe del Consejo Superior de la Guardia Civil.", "al Consejo Superior de la Guardia Civil, previo informe del Director General de la Guardia Civil.", "al Ministro de Defensa, a propuesta del Director General de la Guardia Civil y previo informe del Consejo Superior.", "al Director General de la Guardia Civil, previo informe de la junta de evaluación correspondiente."],
 "La designación de quienes deban entrar en evaluación y de los que asistirán a los citados cursos corresponderá al Director General, previo informe del Consejo Superior de la Guardia Civil.", "Decide el Director General, con informe previo del Consejo Superior.", "media"),
A("art. 71.1", "Ascenso al empleo de Cabo", "El ascenso al empleo de Cabo se producirá por el sistema de concurso-oposición y será requisito la superación de un curso de capacitación. Las plazas se ofertarán con carácter general y a ellas podrán optar los guardias civiles con:",
 ["al menos, dos años de tiempo de servicios en el Cuerpo.", "al menos, tres años de tiempo de servicios en el Cuerpo, salvo los del último empleo.", "al menos, dos años de tiempo de servicios en el empleo de Guardia Civil en destino.", "un máximo de dos años de tiempo de servicios en el Cuerpo, cumplidos en la convocatoria."],
 "a ellas podrán optar los guardias civiles con, al menos, dos años de tiempo de servicios en el Cuerpo", "Se exigen dos años de servicios en el Cuerpo y el sistema es concurso-oposición.", "media"),
A("art. 71.4", "Ascenso al empleo de Cabo", "La obtención del nombramiento de Cabo, siempre que los interesados estén en posesión del título de Bachiller o equivalente, permitirá obtener la equivalencia con el título de:",
 ["Técnico Superior correspondiente a la formación profesional del Sistema Educativo Español, a efectos académicos y de acceso directo a las enseñanzas universitarias oficiales de Grado.", "Técnico Superior correspondiente a la formación profesional del Sistema Educativo Español, a efectos académicos, pero sin acceso directo a las enseñanzas universitarias oficiales de Grado.", "Técnico correspondiente a la formación profesional de grado medio del Sistema Educativo Español, a efectos académicos y de acceso directo a las enseñanzas universitarias oficiales de Grado.", "Técnico Superior correspondiente a la formación profesional del Sistema Educativo Español, a efectos laborales y de acceso directo a las enseñanzas universitarias oficiales de Grado."],
 "permitirá obtener la equivalencia con el título de Técnico Superior correspondiente a la formación profesional del Sistema Educativo Español, a efectos académicos y de acceso directo a las enseñanzas universitarias oficiales de Grado", "Equivale a Técnico Superior, con efectos académicos y de acceso directo a Grado.", "dificil"),
// ---- pág. 117-118 (vacantes para el ascenso y concesión)
A("art. 72.1", "Vacantes para el ascenso", "Señale la respuesta INCORRECTA. Se darán al ascenso las vacantes que se produzcan en los distintos empleos de cada Escala por alguno de los siguientes motivos:",
 ["Cambio de destino dentro de la misma Escala.", "Incorporación a otra escala.", "Pérdida de la condición de guardia civil.", "Fallecimiento o declaración de fallecido."],
 "Se darán al ascenso las vacantes que se produzcan en los distintos empleos de cada Escala por alguno de los siguientes motivos: a) Ascenso. b) Incorporación a otra escala.", "El cambio de destino en la misma Escala no genera vacante para el ascenso; sí la incorporación a otra escala, la pérdida de la condición o el fallecimiento.", "media"),
A("art. 72.2", "Vacantes para el ascenso", "Cuando se produzca una vacante para el ascenso, se considerará como fecha de ésta:",
 ["la del día que surta efectos el acto administrativo que la ocasionó.", "la del día en que se dicte el acto administrativo que la ocasionó.", "la de su publicación en el «Boletín Oficial de la Guardia Civil» tras el acto que la ocasionó.", "la del día siguiente a aquel en que surta efectos el acto administrativo que la ocasionó."],
 "se considerará como fecha de ésta la del día que surta efectos el acto administrativo que la ocasionó", "La fecha de la vacante es la del día en que surte efectos el acto que la origina.", "dificil"),
A("art. 72.2", "Vacantes para el ascenso", "Cuando una vacante dé lugar a ascensos en los empleos inferiores, la fecha de antigüedad con la que se conferirán los nuevos empleos será:",
 ["la misma para todos ellos.", "la del día siguiente a la vacante, distinta para cada uno de ellos.", "la que corresponda a cada uno según su orden de clasificación.", "la de la resolución de ascenso que se dicte para cada uno de ellos."],
 "la fecha de antigüedad con la que se conferirán los nuevos empleos será la misma para todos ellos", "Todos los ascendidos por la misma vacante reciben la misma antigüedad.", "media"),
A("art. 73.1", "Concesión de los ascensos", "Los ascensos a los empleos de la categoría de oficiales generales se concederán por:",
 ["real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Defensa, quien para efectuarla oirá al Ministro del Interior.", "orden del Ministro de Defensa, a propuesta del Director General de la Guardia Civil, quien para efectuarla oirá al Consejo Superior.", "real decreto acordado en Consejo de Ministros, a propuesta del Ministro del Interior, quien para efectuarla oirá al Ministro de Defensa.", "resolución del Director General de la Guardia Civil, previa propuesta del Consejo Superior, oyendo al Ministro del Interior."],
 "Los ascensos a los empleos de la categoría de oficiales generales se concederán por real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Defensa, quien para efectuarla oirá al Ministro del Interior.", "Real decreto, propuesta del Ministro de Defensa y audiencia al Ministro del Interior.", "dificil"),
A("art. 73.2", "Concesión de los ascensos", "La concesión del ascenso al empleo de Coronel, a Suboficial mayor y a Cabo mayor es competencia:",
 ["del Ministro de Defensa, a propuesta del Director General de la Guardia Civil.", "del Director General de la Guardia Civil, previo informe del Consejo Superior.", "del Ministro del Interior, a propuesta del Director General de la Guardia Civil.", "del Consejo de Ministros, a propuesta del Ministro de Defensa."],
 "es competencia del Ministro de Defensa, a propuesta del Director General de la Guardia Civil", "Compete al Ministro de Defensa a propuesta del Director General.", "media"),
// ---- pág. 119 (no aptitud; destinos, principios)
A("art. 74.1", "Declaración de no aptitud para el ascenso", "Quienes sean declarados no aptos para el ascenso no podrán ascender:",
 ["hasta que sean nuevamente evaluados y declarados aptos.", "hasta que transcurra el siguiente ciclo de ascensos y sean nuevamente evaluados.", "hasta que lo autorice el Ministro de Defensa, a propuesta del Director General.", "hasta que se cumpla un año desde la declaración de no aptitud, salvo recurso."],
 "Quienes sean declarados no aptos para el ascenso no podrán ascender hasta que sean nuevamente evaluados y declarados aptos", "Hace falta nueva evaluación con declaración de aptitud.", "media"),
A("art. 74.2", "Declaración de no aptitud para el ascenso", "Si un guardia civil es declarado no apto más de dos veces en la evaluación para el ascenso al mismo empleo, el Director General elevará propuesta al Ministro de Defensa quien, si procede, declarará al afectado no apto para el ascenso:",
 ["con carácter definitivo.", "con carácter temporal durante los dos ciclos de ascenso siguientes.", "hasta su pase a la situación de reserva, sin posibilidad de nueva evaluación.", "con carácter definitivo, previo informe del Consejo Superior de la Guardia Civil."],
 "no apto más de dos veces en la evaluación para el ascenso al mismo empleo, el Director General elevará propuesta al Ministro de Defensa quien, si procede, declarará al afectado no apto para el ascenso con carácter definitivo", "Más de dos no aptos: propuesta al Ministro de Defensa y declaración definitiva.", "dificil"),
A("art. 74.3", "Declaración de no aptitud para el ascenso", "Quienes sean declarados con carácter definitivo no aptos para el ascenso permanecerán en su empleo hasta su pase a la situación de reserva y no podrán ser designados para realizar cursos:",
 ["que no sean de aplicación específica en su empleo, salvo que de la resolución que se adopte en el expediente se derive el pase a retiro.", "que no sean de aplicación específica en su empleo, salvo autorización expresa del Director General de la Guardia Civil.", "de ninguna clase, salvo que de la resolución que se adopte en el expediente se derive el pase a retiro.", "que no sean de aplicación específica en su empleo, salvo que de la resolución que se adopte en el expediente se derive la suspensión de empleo."],
 "no podrán ser designados para realizar cursos que no sean de aplicación específica en su empleo salvo que de la resolución que se adopte en el expediente regulado en el artículo 99 se derive el pase a retiro", "Solo pueden hacer cursos de aplicación específica en su empleo, salvo que el expediente lleve al retiro.", "dificil"),
A("art. 75.2", "Principios generales", "Los destinos del personal del Cuerpo de la Guardia Civil se proveerán conforme a los principios de:",
 ["mérito, capacidad y antigüedad.", "mérito, capacidad y experiencia profesional.", "objetividad, igualdad de oportunidades y mérito.", "mérito, antigüedad y disponibilidad para el servicio."],
 "Los destinos del personal del Cuerpo de la Guardia Civil se proveerán conforme a los principios de mérito, capacidad y antigüedad", "Los principios son mérito, capacidad y antigüedad.", "media"),
A("art. 75.1", "Principios generales", "También tendrá consideración de destino la participación en misiones para mantener la paz y seguridad internacionales:",
 ["si no lo tuviera o cesara en el de origen.", "aunque se conserve el destino de origen y por tiempo superior a seis meses.", "si así lo autoriza el Ministro del Interior, en todo caso.", "siempre que su duración sea superior a un año y conservando el destino."],
 "También tendrá consideración de destino la participación en misiones para mantener la paz y seguridad internacionales, si no lo tuviera o cesara en el de origen", "Solo es destino si el guardia civil no tuviera destino o cesara en el de origen.", "dificil"),
// ---- pág. 120 (clasificación y provisión de destinos)
A("art. 77.1", "Clasificación de los destinos", "Los destinos, según su forma de asignación, son:",
 ["de libre designación, de concurso de méritos o de provisión por antigüedad.", "de libre designación, de concurso-oposición o de provisión por antigüedad.", "de libre designación, de concurso de méritos o de provisión por clasificación.", "de elección, de concurso de méritos o de provisión por antigüedad."],
 "Los destinos, según su forma de asignación, son de libre designación, de concurso de méritos o de provisión por antigüedad", "Libre designación, concurso de méritos y provisión por antigüedad.", "media"),
A("art. 77.2", "Clasificación de los destinos", "Son destinos de libre designación aquéllos para los que, por su especial responsabilidad y confianza, se precisan condiciones profesionales y personales de idoneidad, que apreciará:",
 ["discrecionalmente la autoridad facultada para concederlos, entre los que cumplan los requisitos exigidos para el puesto.", "reglamentariamente la autoridad facultada para concederlos, entre los que cumplan los requisitos exigidos para el puesto.", "discrecionalmente el Consejo Superior de la Guardia Civil, entre los que cumplan los requisitos exigidos para el puesto.", "discrecionalmente la autoridad facultada para concederlos, entre los evaluados para el ascenso al empleo superior."],
 "que apreciará discrecionalmente la autoridad facultada para concederlos, entre los que cumplan los requisitos exigidos para el puesto", "La idoneidad la aprecia discrecionalmente la autoridad que concede el destino.", "dificil"),
A("art. 77", "Clasificación de los destinos", "Señale la respuesta INCORRECTA sobre las formas de asignación de los destinos:",
 ["Son destinos de concurso de méritos aquéllos que se asignan evaluando los méritos y capacidades que se posean, con independencia de los requisitos exigidos para el puesto.", "Son destinos de libre designación aquéllos para los que, por su especial responsabilidad y confianza, se precisan condiciones profesionales y personales de idoneidad.", "Son destinos de concurso de méritos aquéllos que se asignan evaluando los méritos y capacidades que se posean en relación con los requisitos exigidos para el puesto.", "Son destinos de provisión por antigüedad los que se asignan por este criterio, entre los interesados que cumplan los requisitos exigidos para el puesto."],
 "Son destinos de concurso de méritos aquéllos que se asignan evaluando los méritos y capacidades que se posean en relación con los requisitos exigidos para el puesto.", "El concurso de méritos se evalúa siempre en relación con los requisitos del puesto, no con independencia de ellos.", "dificil"),
A("art. 78.1", "Provisión de destinos", "Asimismo, se determinarán los procedimientos de asignación en ausencia de peticionarios o por falta de idoneidad de los mismos, atendiendo a:",
 ["las características de la vacante y a los historiales profesionales de los que puedan ser destinados.", "las características de la vacante y a la antigüedad en el empleo de los que puedan ser destinados.", "las necesidades del servicio y a los historiales profesionales de los que puedan ser destinados.", "las características de la vacante y al criterio de la autoridad competente para su asignación."],
 "atendiendo a las características de la vacante y a los historiales profesionales de los que puedan ser destinados", "Se atiende a las características de la vacante y a los historiales profesionales.", "dificil"),
A("art. 78.2", "Provisión de destinos", "Las vacantes de destinos y su provisión, con indicación de aquellos a quienes se asigne, se publicarán en el «Boletín Oficial de la Guardia Civil», haciendo constar:",
 ["la denominación específica del puesto o la genérica de la unidad, centro u organismo correspondiente, sus características, la forma de asignación, los requisitos que se exijan para su ocupación y los plazos para la presentación de solicitudes.", "únicamente la denominación genérica de la unidad, centro u organismo correspondiente, sus características, la forma de asignación, los requisitos que se exijan para su ocupación y los plazos para la presentación de solicitudes.", "la denominación específica del puesto o la genérica de la unidad, centro u organismo correspondiente, su nivel retributivo, la forma de asignación y los plazos para la presentación de solicitudes.", "la denominación específica del puesto o la genérica de la unidad, centro u organismo correspondiente, sus características, los requisitos y el plazo máximo de resolución del concurso."],
 "haciendo constar la denominación específica del puesto o la genérica de la unidad, centro u organismo correspondiente, sus características, la forma de asignación, los requisitos que se exijan para su ocupación y los plazos para la presentación de solicitudes", "El anuncio incluye denominación, características, forma de asignación, requisitos y plazos de solicitudes.", "dificil"),
A("art. 78.3", "Provisión de destinos", "Los destinos de aquellos que se incorporen a una escala, así como los que se asignen a guardias civiles víctimas de violencia de género o tengan el reconocimiento de víctima del terrorismo, podrán otorgarse:",
 ["sin publicación previa de la vacante correspondiente.", "sin informe previo del Director General de la Guardia Civil, aunque con publicación de la vacante.", "con publicación previa de la vacante, pero sin plazo para la presentación de solicitudes.", "sin necesidad de que cumplan los requisitos exigidos para el puesto de que se trate."],
 "podrán otorgarse sin publicación previa de la vacante correspondiente", "Pueden otorgarse sin publicar previamente la vacante.", "media"),
A("art. 79", "Nombramientos, destinos y ceses de oficiales generales", "Los nombramientos o asignaciones y los ceses de los cargos y destinos correspondientes a oficiales generales serán competencia:",
 ["del Ministro del Interior.", "del Ministro de Defensa, previo informe del Ministro del Interior.", "del Consejo de Ministros, a propuesta del Ministro del Interior.", "del Secretario de Estado de Seguridad, por delegación del Ministro."],
 "Los nombramientos o asignaciones y los ceses de los cargos y destinos correspondientes a oficiales generales, serán competencia del Ministro del Interior.", "Es competencia del Ministro del Interior.", "media"),
// ---- pág. 121 (asignación de destinos; atención a la familia)
A("art. 80.1", "Asignación de destinos", "Los destinos, cualquiera que fuese su forma de asignación, podrán ser asignados con carácter:",
 ["voluntario, forzoso o anuente, con arreglo a lo que reglamentariamente se establezca.", "voluntario o forzoso, con arreglo a lo que reglamentariamente se establezca.", "voluntario, forzoso o provisional, con arreglo a lo que reglamentariamente se establezca.", "voluntario, forzoso o anuente, previo informe del Consejo Superior de la Guardia Civil."],
 "podrán ser asignados con carácter voluntario, forzoso o anuente, con arreglo a lo que reglamentariamente se establezca", "Voluntario, forzoso o anuente.", "dificil"),
A("art. 80.2", "Asignación de destinos", "La asignación de los destinos de libre designación que correspondan a puestos de mando o dirección que determine el Ministro del Interior serán competencia:",
 ["del Secretario de Estado de Seguridad.", "del Director General de la Guardia Civil, previo informe del Consejo Superior.", "del Ministro de Defensa, a propuesta del Director General de la Guardia Civil.", "del Subsecretario del Interior, oído el Director General de la Guardia Civil."],
 "serán competencia del Secretario de Estado de Seguridad", "Los puestos de mando o dirección de libre designación los asigna el Secretario de Estado de Seguridad.", "dificil"),
A("art. 81.1", "Atención a la familia", "Durante el período de embarazo y previo informe facultativo, la mujer guardia civil tendrá derecho a ocupar un puesto orgánico o cometido distinto del que estuviera ocupando, adecuado a las circunstancias de su estado. La aplicación de este supuesto:",
 ["no supondrá pérdida del destino.", "supondrá la pérdida del destino, que se recuperará al finalizar la situación de embarazo.", "no supondrá pérdida del destino, aunque sí de los complementos del puesto anterior.", "supondrá una comisión de servicio con derecho a indemnización por razón del servicio."],
 "La aplicación de este supuesto no supondrá pérdida del destino", "Cambiar de puesto durante el embarazo no implica perder el destino.", "media"),
A("art. 81.2", "Atención a la familia", "Cuando existan circunstancias excepcionales de atención familiar, basadas en motivos de salud, discapacidad o rehabilitación del guardia civil, su cónyuge, hijos o familiares hasta segundo grado de consanguinidad, se podrá adscribir temporalmente al guardia civil a un puesto de trabajo en distinta unidad o localidad, conservando el destino que tuviera, previa solicitud del interesado y previo informe:",
 ["del servicio médico oficial legalmente establecido.", "de cualquier facultativo colegiado designado por el interesado.", "del Consejo Superior de la Guardia Civil, a propuesta del jefe de unidad.", "de la Junta de Evaluación de la Dirección General de la Guardia Civil."],
 "previa solicitud del interesado, informe del servicio médico oficial legalmente establecido y siempre que concurran las siguientes condiciones", "El informe lo emite el servicio médico oficial legalmente establecido.", "media"),
A("art. 81.2", "Atención a la familia", "Para la adscripción temporal por circunstancias excepcionales de atención familiar, es condición que existan puestos vacantes en la plantilla de la unidad de adscripción cuyo nivel de complemento de destino y componente singular del complemento específico:",
 ["no sea superior al del puesto de destino.", "no sea inferior al del puesto de destino que se ocupe en el momento de la solicitud.", "sea igual al del puesto de destino, sin que pueda ser superior ni inferior.", "no exceda en más de un nivel del correspondiente al puesto de destino."],
 "cuyo nivel de complemento de destino y componente singular del complemento específico no sea superior al del puesto de destino", "El nivel del puesto de adscripción no puede ser superior al del puesto de destino.", "dificil"),
A("art. 81.3", "Atención a la familia", "La adscripción temporal por circunstancias excepcionales de atención familiar se concederá mediante Resolución del Director General, publicada en el «Boletín Oficial de la Guardia Civil», por periodos renovables de un año, sin que el tiempo total de adscripción pueda superar:",
 ["los cuatro años. Entrará en vigor a los cinco días de su publicación, salvo que la resolución disponga otro plazo.", "los dos años. Entrará en vigor a los cinco días de su publicación, salvo que la resolución disponga otro plazo.", "los cuatro años. Entrará en vigor a los diez días de su publicación, salvo que la resolución disponga otro plazo.", "los cuatro años. Entrará en vigor el día siguiente al de su publicación, salvo que la resolución disponga otro plazo."],
 "sin que el tiempo total de adscripción pueda superar los cuatro años. Entrará en vigor a los cinco días de su publicación, salvo que la resolución disponga otro plazo", "Cuatro años como máximo, con periodos de un año, y entrada en vigor a los cinco días.", "dificil"),
// ---- pág. 122 (violencia de género; cese en los destinos)
A("art. 82", "Violencia de género y condición de víctima del terrorismo", "La guardia civil víctima de violencia de género que se vea obligada a cesar en su destino para hacer efectiva su protección o su derecho a la asistencia social integral, tendrá derecho, en las condiciones que reglamentariamente se determinen, a ocupar otro destino de análogas características:",
 ["sin necesidad de que sea vacante de necesaria cobertura.", "siempre que sea vacante de necesaria cobertura.", "sin necesidad de publicación previa, pero siempre que sea vacante de necesaria cobertura.", "previo informe del Director General de la Guardia Civil y en vacante de necesaria cobertura."],
 "tendrá derecho, en las condiciones que reglamentariamente se determinen, a ocupar otro destino de análogas características, sin necesidad de que sea vacante de necesaria cobertura", "El nuevo destino no tiene que ser vacante de necesaria cobertura.", "dificil"),
A("art. 82", "Violencia de género y condición de víctima del terrorismo", "Los guardias civiles que sean considerados víctimas del terrorismo, conforme a lo previsto en la ley de Reconocimiento y Protección Integral a las Víctimas del Terrorismo, tendrán derecho, en las condiciones que reglamentariamente se determinen, a:",
 ["la asignación de un nuevo destino.", "ocupar otro destino de análogas características, sin necesidad de que sea vacante.", "la asignación de un nuevo destino, siempre que sea vacante de necesaria cobertura.", "la adscripción temporal a un puesto en distinta unidad o localidad, por un año."],
 "tendrán derecho a la asignación de un nuevo destino, los guardias civiles que sean considerados víctimas del terrorismo", "A las víctimas del terrorismo les corresponde la asignación de un nuevo destino.", "media"),
A("art. 83.1", "Cese en los destinos", "Las normas generales de provisión de destinos incluirán las causas de cese en los mismos. En todo caso, los destinos de libre designación podrán ser:",
 ["revocados libremente por las autoridades competentes para su asignación.", "revocados por el Director General, previo expediente con audiencia del interesado.", "revocados únicamente por falta de idoneidad, previo informe motivado del jefe de unidad.", "revocados libremente por el Ministro del Interior, sin que sea necesaria motivación alguna."],
 "los destinos de libre designación podrán ser revocados libremente por las autoridades competentes para su asignación", "Los de libre designación se revocan libremente por la autoridad que los asigna.", "media"),
A("art. 83.2", "Cese en los destinos", "El cese en un destino asignado por concurso de méritos o por antigüedad deberá ser motivado con indicación de las causas, previa apertura, en su caso, de un expediente en el que se requerirá:",
 ["la audiencia del interesado, cuyas manifestaciones constarán por escrito.", "la audiencia del interesado, cuyas manifestaciones podrán constar verbalmente.", "el informe del Consejo Superior de la Guardia Civil, que constará por escrito.", "el informe previo del jefe de la unidad, cuyas manifestaciones constarán por escrito."],
 "un expediente en el que se requerirá la audiencia del interesado, cuyas manifestaciones constarán por escrito", "Se exige audiencia del interesado, con sus manifestaciones por escrito.", "dificil"),
A("art. 83.3", "Cese en los destinos", "Los jefes de unidad, centro u organismo podrán proponer el cese en el destino de cualquier subordinado por falta de idoneidad en el desempeño de los cometidos propios de su destino, elevando por conducto reglamentario a la autoridad que lo confirió:",
 ["informe razonado de las causas que motivan la propuesta de cese.", "informe de la junta de evaluación sobre las causas que motivan la propuesta de cese.", "informe favorable del interesado sobre las causas que motivan la propuesta de cese.", "informe del Consejo Superior sobre las causas que motivan la propuesta de cese."],
 "elevando por conducto reglamentario a la autoridad que lo confirió, informe razonado de las causas que motivan la propuesta de cese", "Se eleva informe razonado de las causas.", "media"),
A("art. 83.4", "Cese en los destinos", "La imposición de condena por sentencia firme, que imposibilite para el ejercicio de las funciones propias del destino que se ocupe, llevará aparejada el cese en éste, desde el momento en que:",
 ["la Dirección General de la Guardia Civil tuviere testimonio de la resolución judicial.", "la sentencia sea notificada al interesado por el órgano judicial correspondiente.", "se dicte la sentencia por el órgano judicial, aunque no se haya notificado.", "el Ministro del Interior tuviere conocimiento de la resolución judicial firme."],
 "llevará aparejada el cese en éste, desde el momento en que la Dirección General de la Guardia Civil tuviere testimonio de la resolución judicial", "El cese opera desde que la Dirección General tiene testimonio de la resolución judicial.", "dificil"),
// ---- pág. 123 (carácter de los destinos; comisiones de servicio)
A("art. 85", "Carácter de los destinos", "Los destinos no podrán ser asignados a personal con empleos superiores ni inferiores a los previstos para el puesto específico, a no ser, en este último caso, que su designación se efectúe:",
 ["en vacante de empleo inmediato superior.", "en vacante de empleo inmediato inferior, previo informe.", "en vacante de la misma Escala, con carácter forzoso.", "en vacante de cualquier empleo superior, de la misma Escala."],
 "a no ser, en este último caso, que su designación se efectúe en vacante de empleo inmediato superior", "Excepcionalmente se asigna un empleo inferior al del puesto si es en vacante de empleo inmediato superior.", "dificil"),
A("art. 85", "Carácter de los destinos", "Cuando razones organizativas o estructurales así lo requieran, podrán igualmente asignarse destinos de empleos inmediatamente superiores y dentro de la misma Escala, para las zonas del escalafón que se determinen en el anuncio de la vacante, siempre que:",
 ["los posibles peticionarios hayan sido evaluados para el ascenso y la vacante no tenga peticionarios del empleo para el que esté catalogada.", "los posibles peticionarios hayan sido evaluados para el ascenso o la vacante no tenga peticionarios del empleo para el que esté catalogada.", "los posibles peticionarios hayan sido declarados aptos para el ascenso y la vacante tenga peticionarios del empleo para el que esté catalogada.", "los posibles peticionarios hayan superado el curso de capacitación y la vacante no tenga peticionarios del empleo para el que esté catalogada."],
 "siempre que los posibles peticionarios hayan sido evaluados para el ascenso y la vacante no tenga peticionarios del empleo para el que esté catalogada", "Se exigen las dos condiciones a la vez: evaluados y sin peticionarios del empleo catalogado.", "dificil"),
A("art. 85", "Carácter de los destinos", "Las funciones de un cargo o puesto vacantes se podrán desempeñar con carácter interino o accidental por aquél al que le corresponda, de acuerdo con:",
 ["lo que se determine reglamentariamente.", "lo que disponga el Director General de la Guardia Civil en cada caso.", "lo que establezca el jefe de la unidad, centro u organismo correspondiente.", "lo previsto en el catálogo de puestos de trabajo de la Guardia Civil."],
 "se podrán desempeñar con carácter interino o accidental por aquél al que le corresponda, de acuerdo con lo que se determine reglamentariamente", "Se remite a lo que se determine reglamentariamente.", "media"),
A("art. 86.1", "Comisiones de servicio", "Cuando las necesidades del servicio lo requieran, los guardias civiles podrán ser designados para realizar comisiones de servicio de carácter temporal, conservando:",
 ["su destino si lo tuvieran.", "su destino, aunque percibiendo las retribuciones del puesto de la comisión.", "su empleo, pero no su destino, que quedará vacante.", "su destino, con carácter indefinido, si lo tuvieran y así lo solicitan."],
 "podrán ser designados para realizar comisiones de servicio de carácter temporal, conservando su destino si lo tuvieran", "Las comisiones de servicio son temporales y se conserva el destino si se tiene.", "media"),
A("art. 86.2", "Comisiones de servicio", "La duración de las comisiones de servicio no podrá exceder de:",
 ["un año, salvo que el régimen específico aplicable a los expertos nacionales en comisión de servicio en el ámbito de la Unión Europea u otro Organismo Internacional establezca una duración superior.", "seis meses, salvo que el régimen específico aplicable a los expertos nacionales en comisión de servicio en el ámbito de la Unión Europea u otro Organismo Internacional establezca una duración superior.", "dos años, salvo que el régimen específico aplicable a los expertos nacionales en comisión de servicio en el ámbito de la Unión Europea u otro Organismo Internacional establezca una duración superior.", "un año, sin excepción alguna, incluidos los expertos nacionales en comisión de servicio en el ámbito de la Unión Europea u otro Organismo Internacional."],
 "La duración de las comisiones de servicio no podrá exceder de un año, salvo que el régimen específico aplicable a los expertos nacionales en comisión de servicio en el ámbito de la Unión Europea u otro Organismo Internacional establezca una duración superior", "Un año, con excepción para los expertos nacionales en la UE u organismos internacionales.", "dificil"),
A("art. 86.3", "Comisiones de servicio", "Cuando existan circunstancias excepcionales de atención familiar, la comisión de servicios podrá prolongarse durante el tiempo que se mantengan las referidas circunstancias, sin que en ningún caso pueda exceder de:",
 ["un año.", "dos años.", "tres años.", "seis meses."],
 "la comisión de servicios podrá prolongarse durante el tiempo que se mantengan las referidas circunstancias, sin que en ningún caso pueda exceder de un año", "El tope sigue siendo un año.", "media"),
// ---- pág. 124 (situaciones administrativas; servicio activo; inicio de servicios especiales)
A("art. 87.1", "Situaciones administrativas", "Señale la respuesta INCORRECTA. Los guardias civiles se hallarán en alguna de las siguientes situaciones administrativas:",
 ["Excedencia forzosa.", "Servicios especiales.", "Suspensión de funciones.", "Reserva."],
 "Los guardias civiles se hallarán en alguna de las siguientes situaciones administrativas: a) Servicio activo. b) Servicios especiales. c) Excedencia. d) Suspensión de empleo. e) Suspensión de funciones. f) Reserva.", "Las situaciones son servicio activo, servicios especiales, excedencia, suspensión de empleo, suspensión de funciones y reserva; no existe la excedencia forzosa.", "media"),
A("art. 87.2", "Situaciones administrativas", "El guardia civil en cualquier situación administrativa, salvo en los casos en que se especifica lo contrario, está sujeto:",
 ["al régimen general de derechos y deberes de los miembros de la Guardia Civil, a su régimen disciplinario y a las leyes penales y disciplinarias militares cuando les sean de aplicación.", "al régimen general de derechos y deberes de los miembros de la Guardia Civil, a su régimen disciplinario y a las leyes penales militares, pero no a las disciplinarias militares.", "al régimen general de derechos y deberes de los miembros de la Guardia Civil y a su régimen disciplinario, pero no a las leyes penales y disciplinarias militares aunque les sean de aplicación.", "al régimen general de derechos y deberes de los miembros de la Guardia Civil, a su régimen disciplinario y a las leyes penales y disciplinarias militares en todo caso."],
 "está sujeto al régimen general de derechos y deberes de los miembros de la Guardia Civil, a su régimen disciplinario y a las leyes penales y disciplinarias militares cuando les sean de aplicación", "Aplica el régimen general, el disciplinario y las leyes penales y disciplinarias militares cuando proceda.", "dificil"),
A("art. 88.2", "Situación de servicio activo", "También se hallarán en servicio activo cuando estén pendientes de asignación de destino por haber cesado en el que tuvieran o por proceder de otra situación administrativa y cuando ingresen como alumnos en los centros docentes de formación, si:",
 ["no les correspondiera el pase a otra conforme a lo dispuesto en este Capítulo.", "no les correspondiera el pase a otra, aunque lo solicitaran expresamente los interesados.", "les correspondiera el pase a la situación de excedencia por prestación de servicios en el sector público.", "no hubieran superado el curso de capacitación para el ascenso al empleo inmediato superior."],
 "si no les correspondiera el pase a otra conforme a lo dispuesto en este Capítulo", "Siguen en servicio activo salvo que les corresponda otra situación.", "media"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando sean elegidos por las Cortes Generales o las Asambleas legislativas de las Comunidades Autónomas para formar parte de los órganos constitucionales, o de los órganos estatutarios, u otros cuya elección corresponda:",
 ["a las Cámaras y a las Asambleas Legislativas de las Comunidades Autónomas.", "al Gobierno de la Nación y a los Gobiernos de las Comunidades Autónomas.", "al Congreso de los Diputados y a los Parlamentos de las Comunidades Autónomas.", "a las Cámaras y a las Asambleas Legislativas, previa autorización del Ministro del Interior."],
 "u otros cuya elección corresponda a las Cámaras y a las Asambleas Legislativas de las Comunidades Autónomas", "La elección corresponde a las Cámaras y a las Asambleas Legislativas autonómicas.", "dificil"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando presten servicios en:",
 ["el Tribunal Constitucional, Defensor del Pueblo, Consejo General del Poder Judicial o Tribunal de Cuentas, Tribunal Supremo o en otros órganos jurisdiccionales.", "el Tribunal Constitucional, Defensor del Pueblo, Consejo de Estado o Tribunal de Cuentas, Tribunal Supremo o en otros órganos jurisdiccionales.", "el Tribunal Constitucional, Defensor del Pueblo, Consejo General del Poder Judicial o Tribunal de Cuentas, pero no en el Tribunal Supremo ni en otros órganos jurisdiccionales.", "el Tribunal Constitucional, Fiscalía General del Estado, Consejo General del Poder Judicial o Tribunal de Cuentas, Tribunal Supremo o en otros órganos jurisdiccionales."],
 "Presten servicios en el Tribunal Constitucional, Defensor del Pueblo, Consejo General del Poder Judicial o Tribunal de Cuentas, Tribunal Supremo o en otros órganos jurisdiccionales.", "La enumeración incluye el Consejo General del Poder Judicial, el Tribunal Supremo y otros órganos jurisdiccionales.", "dificil"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando presten servicios en la Presidencia del Gobierno o en los Gabinetes de Ministros y Secretarios de Estado en puestos orgánicos:",
 ["no relacionados específicamente con la defensa o la seguridad ciudadana.", "relacionados específicamente con la defensa o la seguridad ciudadana.", "no relacionados con la seguridad ciudadana, aunque sí con la defensa nacional.", "no relacionados específicamente con la seguridad ciudadana ni con la organización del Cuerpo."],
 "en puestos orgánicos no relacionados específicamente con la defensa o la seguridad ciudadana", "Solo pasan a servicios especiales si el puesto no se relaciona con la defensa o la seguridad ciudadana.", "dificil"),
// ---- pág. 125 (servicios especiales; excedencia: modalidades)
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando sean nombrados para desempeñar puestos o cargos en organismos públicos, o entidades dependientes o vinculados a las Administraciones públicas que, de conformidad con lo que establezca la normativa de la respectiva Administración pública, estén asimilados en su rango administrativo a:",
 ["alto cargo.", "personal directivo de nivel superior.", "jefe de servicio de nivel superior.", "funcionario de carrera del subgrupo A1."],
 "estén asimilados en su rango administrativo a alto cargo", "Deben estar asimilados en rango administrativo a alto cargo.", "media"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando sean autorizados por el Ministro del Interior a participar en el desarrollo de programas específicos de interés para la seguridad ciudadana en organismos, entidades o empresas:",
 ["ajenos al Ministerio del Interior.", "dependientes del Ministerio del Interior, únicamente.", "ajenos al Ministerio del Interior, por un período superior a seis meses.", "ajenos al Ministerio de Defensa y al Ministerio del Interior."],
 "programas específicos de interés para la seguridad ciudadana en organismos, entidades o empresas ajenos al Ministerio del Interior", "Los organismos, entidades o empresas son ajenos al Ministerio del Interior.", "media"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando adquieran la condición de:",
 ["personal estatutario permanente del Centro Nacional de Inteligencia.", "personal laboral fijo del Centro Nacional de Inteligencia.", "funcionario de carrera del Centro Nacional de Inteligencia.", "personal estatutario temporal del Centro Nacional de Inteligencia."],
 "Adquieran la condición de personal estatutario permanente del Centro Nacional de Inteligencia", "Se exige ser personal estatutario permanente del CNI.", "dificil"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando sean designados miembros del Gobierno o de los órganos de Gobierno de las Comunidades Autónomas o ciudades de Ceuta o Melilla, o miembros de las Instituciones de la Unión Europea o de Organizaciones Internacionales, o sean nombrados:",
 ["altos cargos de las citadas Administraciones Públicas o Instituciones.", "directivos de las citadas Administraciones Públicas, Instituciones u organismos autónomos.", "altos cargos de cualquier Administración Pública, aunque no sea de las citadas.", "altos cargos de las citadas Administraciones, pero no de las Instituciones."],
 "o sean nombrados altos cargos de las citadas Administraciones Públicas o Instituciones", "Se incluyen los altos cargos de las citadas Administraciones Públicas o Instituciones.", "dificil"),
A("art. 89.1", "Situación de servicios especiales", "Los guardias civiles pasarán a la situación de servicios especiales cuando adquieran la condición de funcionarios al servicio de organizaciones internacionales, en el caso de que:",
 ["no ocupen puestos orgánicos relacionados con la seguridad.", "ocupen puestos orgánicos relacionados con la seguridad.", "no ocupen puestos orgánicos, aunque estén relacionados con la seguridad.", "ocupen puestos orgánicos relacionados con la seguridad, previa autorización del Ministro del Interior."],
 "en el caso de que no ocupen puestos orgánicos relacionados con la seguridad", "Solo si no ocupan puestos orgánicos relacionados con la seguridad.", "dificil"),
A("art. 89.2", "Situación de servicios especiales", "El tiempo permanecido en la situación de servicios especiales será computable a efectos de:",
 ["tiempo de servicios, trienios y de determinación de los derechos de Seguridad Social que corresponda.", "tiempo de servicios y trienios, pero no de determinación de los derechos de Seguridad Social que corresponda.", "tiempo de servicios y de determinación de los derechos de Seguridad Social, pero no de trienios.", "trienios y de determinación de los derechos de Seguridad Social, pero no de tiempo de servicios."],
 "será computable a efectos de tiempo de servicios, trienios y de determinación de los derechos de Seguridad Social que corresponda", "Computa para tiempo de servicios, trienios y Seguridad Social.", "dificil"),
A("art. 89.5", "Situación de servicios especiales", "Durante el tiempo de permanencia en la situación de servicios especiales, el guardia civil tendrá su condición de guardia civil en suspenso y, en consecuencia, dejará de estar sujeto:",
 ["al régimen general de derechos y obligaciones de los miembros del Cuerpo, a las leyes penales militares cuando sean de aplicación y a la disciplinaria del Instituto.", "al régimen general de derechos y obligaciones de los miembros del Cuerpo y a la disciplinaria del Instituto, pero seguirá sujeto a las leyes penales militares.", "al régimen general de derechos y obligaciones de los miembros del Cuerpo, pero seguirá sujeto a las leyes penales militares y a la disciplinaria del Instituto.", "a las leyes penales militares cuando sean de aplicación y a la disciplinaria del Instituto, pero no al régimen de derechos y obligaciones."],
 "tendrá su condición de guardia civil en suspenso y, en consecuencia, dejará de estar sujeto al régimen general de derechos y obligaciones de los miembros del Cuerpo, a las leyes penales militares cuando sean de aplicación y a la disciplinaria del Instituto", "Con la condición en suspenso deja de estar sujeto al régimen de derechos y obligaciones, a las leyes penales militares y a la disciplinaria.", "dificil"),
A("art. 90.1", "Situación de excedencia", "Señale la respuesta INCORRECTA. Los guardias civiles podrán pasar a la situación de excedencia en las siguientes modalidades:",
 ["Excedencia forzosa por razón del servicio.", "Excedencia voluntaria por agrupación familiar.", "Excedencia por cuidado de familiares.", "Excedencia basada en la consideración de víctima de terrorismo."],
 "d) Excedencia por cuidado de familiares. e) Excedencia por razón de violencia de género. f) Ingreso por acceso directo como alumno de los centros de formación. g) Excedencia basada en la consideración de víctima de terrorismo.", "La excedencia forzosa por razón del servicio no figura entre las modalidades.", "media"),
// ---- pág. 126 (excedencia por prestación de servicios en el sector público; voluntaria por interés particular)
A("art. 90.2", "Situación de excedencia", "Los guardias civiles quedarán en situación de excedencia por prestación de servicios en el sector público, cuando pasen a prestar servicios en otras administraciones u organismos del sector público, siempre que se trate del desempeño de puestos con carácter de:",
 ["funcionario de carrera o de personal laboral fijo.", "funcionario de carrera o de personal laboral temporal.", "funcionario interino o de personal laboral fijo.", "funcionario de carrera, pero no de personal laboral."],
 "siempre que se trate del desempeño de puestos con carácter de funcionario de carrera o de personal laboral fijo", "Solo puestos de funcionario de carrera o personal laboral fijo.", "dificil"),
A("art. 90.2", "Situación de excedencia", "Para optar a la excedencia por prestación de servicios en el sector público, el tiempo que se fije desde la adquisición de la condición de guardia civil, que no podrá ser superior a __________, guardará una proporción adecuada a los costes y duración de los estudios realizados y tendrá presente las necesidades de planeamiento de la Guardia Civil.",
 ["ocho años", "doce años", "diez años", "quince años"],
 "el tiempo que se fije, que no podrá ser superior a ocho años, guardará una proporción adecuada a los costes y duración de los estudios realizados", "En esta excedencia el tope es de ocho años; en la voluntaria por interés particular es de doce.", "dificil"),
A("art. 90.2", "Situación de excedencia", "Quienes se hallen en excedencia por prestación de servicios en el sector público tendrán su condición de guardia civil en suspenso, pero podrán ascender:",
 ["durante los dos primeros años de permanencia siempre que tengan cumplidas las condiciones de ascenso establecidas en esta Ley.", "durante todo el tiempo de permanencia siempre que tengan cumplidas las condiciones de ascenso establecidas en esta Ley.", "durante los tres primeros años de permanencia siempre que tengan cumplidas las condiciones de ascenso establecidas en esta Ley.", "durante los dos primeros años de permanencia, aunque no tengan cumplidas las condiciones de ascenso establecidas en esta Ley."],
 "pero podrán ascender durante los dos primeros años de permanencia siempre que tengan cumplidas las condiciones de ascenso establecidas en esta Ley", "Solo pueden ascender durante los dos primeros años y con las condiciones cumplidas.", "dificil"),
A("art. 90.3", "Situación de excedencia", "Los guardias civiles podrán obtener la excedencia voluntaria por interés particular cuando lo soliciten con el preaviso que se determine reglamentariamente, siempre que no estén designados para participar en misiones fuera del territorio nacional ni se les esté instruyendo:",
 ["un procedimiento disciplinario y hubiesen cumplido el tiempo de servicios que reglamentariamente se determine.", "un procedimiento disciplinario o penal y hubiesen cumplido el tiempo de servicios que se determine por orden ministerial.", "un procedimiento disciplinario, aunque no hubiesen cumplido el tiempo de servicios que reglamentariamente se determine.", "un procedimiento penal y hubiesen cumplido el tiempo de servicios que reglamentariamente se determine."],
 "ni se les esté instruyendo un procedimiento disciplinario y hubiesen cumplido el tiempo de servicios que reglamentariamente se determine desde la adquisición de la condición de guardia civil", "Requiere no estar designado para misiones en el extranjero ni tener procedimiento disciplinario en instrucción.", "dificil"),
A("art. 90.3", "Situación de excedencia", "En la excedencia voluntaria por interés particular, el tiempo de servicios que se fije, que no podrá ser superior a __________, guardará una proporción adecuada a los costes y duración de los estudios realizados y tendrá presente las necesidades de planeamiento de la guardia civil.",
 ["doce años", "diez años", "ocho años", "quince años"],
 "que no podrá ser superior a doce años, guardará una proporción adecuada a los costes y duración de los estudios realizados", "En la voluntaria por interés particular el tope es de doce años.", "dificil"),
A("art. 90.3", "Situación de excedencia", "En la excedencia voluntaria por interés particular se permanecerá un tiempo mínimo de dos años, transcurridos los cuales el interesado permanecerá en el escalafón correspondiente en el puesto que ocupara en ese momento y:",
 ["no será evaluado para el ascenso.", "será evaluado para el ascenso con efectos desde su reincorporación.", "perderá un puesto en el escalafón por cada año de permanencia.", "podrá ascender en cualquier momento si cumple los requisitos de su escala."],
 "transcurridos los cuales el interesado permanecerá en el escalafón correspondiente en el puesto que ocupara en ese momento y no será evaluado para el ascenso", "Queda inmovilizado en el escalafón y sin ser evaluado para el ascenso.", "dificil"),
A("art. 90.3", "Situación de excedencia", "La concesión de excedencia voluntaria por interés particular quedará subordinada a:",
 ["las necesidades del servicio debidamente motivadas.", "la existencia de vacante en la escala de procedencia del interesado.", "la autorización expresa del Ministro del Interior, a propuesta del Director General.", "la disponibilidad presupuestaria que se determine anualmente."],
 "La concesión de excedencia voluntaria por interés particular quedará subordinada a las necesidades del servicio debidamente motivadas", "Se subordina a las necesidades del servicio, motivadas.", "media"),
A("art. 90.4", "Situación de excedencia", "A los guardias civiles se les podrá conceder la excedencia voluntaria por agrupación familiar, cuando el cónyuge resida en otro municipio por haber obtenido y estar desempeñando un puesto de trabajo de carácter definitivo, como funcionario de carrera o laboral en cualquiera de las Administraciones Públicas, sin requisito de:",
 ["haber prestado tiempo de servicios.", "haber superado un periodo de prueba en el último destino.", "haber cumplido dos años de servicio activo en el empleo.", "haber sido evaluado para el ascenso al empleo superior."],
 "se les podrá conceder la excedencia voluntaria por agrupación familiar, sin requisito de haber prestado tiempo de servicios", "No se exige tiempo de servicios previo.", "media"),
];
exports.Q = Q;
if (require.main === module) require('./preguntas-t26r-lib.js').run({ bloque: 12, Q });
